# Callable-content analysis is intentionally independent from structural
# resolution completeness.  An opaque numeric vector, for example, may be
# impossible to enumerate while still being proven unable to contain a local
# function object.  Keep this five-state vocabulary explicit: downstream
# joins must never use ordinary ``complete``/``incomplete`` scan status as a
# substitute for callable capability.
KNOWN_CALLABLE_CONTENT = "KNOWN_CALLABLE_CONTENT"
MAY_CONTAIN_CALLABLE = "MAY_CONTAIN_CALLABLE"
PROVEN_NON_CALLABLE_OPAQUE = "PROVEN_NON_CALLABLE_OPAQUE"
EXACT_NON_CALLABLE = "EXACT_NON_CALLABLE"
UNRESOLVED = "UNRESOLVED"

VALUE_KINDS = frozenset({
    KNOWN_CALLABLE_CONTENT,
    MAY_CONTAIN_CALLABLE,
    PROVEN_NON_CALLABLE_OPAQUE,
    EXACT_NON_CALLABLE,
    UNRESOLVED,
})


def _join_value_kinds(left: str, right: str) -> str:
    """Return the deterministic, commutative callable-content join.

    Concrete callable targets are retained separately by the resolver.  A
    known target joined with an unresolved alternative therefore becomes
    ``MAY_CONTAIN_CALLABLE`` without discarding that concrete target.
    """
    if left not in VALUE_KINDS or right not in VALUE_KINDS:
        raise P541BR2Error("invalid abstract value kind")
    if left == right:
        return left
    pair = frozenset({left, right})
    if MAY_CONTAIN_CALLABLE in pair:
        return MAY_CONTAIN_CALLABLE
    if pair == frozenset({KNOWN_CALLABLE_CONTENT, UNRESOLVED}):
        return MAY_CONTAIN_CALLABLE
    if KNOWN_CALLABLE_CONTENT in pair:
        return KNOWN_CALLABLE_CONTENT
    if UNRESOLVED in pair:
        return UNRESOLVED
    # The only remaining unequal pair is exact plus opaque non-callable.
    return PROVEN_NON_CALLABLE_OPAQUE


def _join_many_value_kinds(
    kinds: Iterable[str], *, empty: str = EXACT_NON_CALLABLE
) -> str:
    result = empty
    for kind in kinds:
        result = _join_value_kinds(result, kind)
    return result


def _kind_may_contain_callable(kind: str) -> bool:
    if kind not in VALUE_KINDS:
        raise P541BR2Error("invalid abstract value kind")
    return kind in {
        MAY_CONTAIN_CALLABLE,
        UNRESOLVED,
    }

