    def dependency_signature_for(
        candidates: ast.AST | Sequence[ast.AST],
        *,
        include_publication: bool = False,
    ) -> tuple[tuple[str, int, str, int], ...]:
        nodes_for_signature = (
            (candidates,)
            if isinstance(candidates, ast.AST)
            else tuple(candidates)
        )
        dependencies: set[tuple[int, str]] = set()
        for candidate in nodes_for_signature:
            dependencies.update(
                structural_dependency_names.get(candidate, frozenset())
            )
        return runtime_delta.signature(
            frozenset(dependencies),
            include_publication=include_publication,
        )
    structure_dump_cache: dict[ast.AST, str] = {}

